G.minesweeper=function(container,_a){var onWin=_a.onWin,onLose=_a.onLose;var W=9,H=9,MINES=10;var cells=[],revealed=0,gameOver=false;var board=document.createElement('div');board.style.cssText='display:grid;grid-template-columns:repeat('+W+',36px);gap:2px;justify-content:center;padding:8px;';var mines=new Set();while(mines.size<MINES)mines.add(Math.floor(Math.random()*W*H));function getAdj(idx){var x=idx%W,y=Math.floor(idx/W);var adj=[];for(var dy=-1;dy<=1;dy++)for(var dx=-1;dx<=1;dx++)if(dx||dy){var nx=x+dx,ny=y+dy;if(nx>=0&&nx<W&&ny>=0&&ny<H)adj.push(ny*W+nx)}return adj}function cnt(idx){return getAdj(idx).filter(function(i){return mines.has(i)}).length}function rvl(idx){if(gameOver||cells[idx].revealed||cells[idx].flagged)return;cells[idx].revealed=true;cells[idx].el.style.background='#1a1a2e';cells[idx].el.style.borderColor='#333';if(mines.has(idx)){cells[idx].el.textContent='💣';cells[idx].el.style.background='#ff4444';gameOver=true;onLose()}else{revealed++;cells[idx].el.textContent=cnt(idx)||'';if(revealed===W*H-MINES){gameOver=true;onWin()}else{var adj=getAdj(idx);for(var i=0;i<adj.length;i++)if(!cnt(idx))rvl(adj[i])}}}function flag(e,idx){e.preventDefault();if(gameOver||cells[idx].revealed)return;cells[idx].flagged=!cells[idx].flagged;cells[idx].el.textContent=cells[idx].flagged?'🚩':'';cells[idx].el.style.background=cells[idx].flagged?'#2a1a1a':'transparent'}for(var i=0;i<W*H;i++){var el=document.createElement('div');el.style.cssText='width:36px;height:36px;background:transparent;border:2px solid #555;border-radius:4px;display:flex;align-items:center;justify-content:center;font-size:16px;cursor:pointer;color:#fff;';el.addEventListener('click',rvl.bind(null,i));el.addEventListener('contextmenu',function(e,i){flag(e,i)}.bind(null,i));board.appendChild(el);cells.push({el:el,revealed:false,flagged:false})}container.innerHTML='';container.appendChild(board);addStyle(container,'body{background:#0d0d1a}')};

