G.frogger=function(c,a){var w=a.onWin,l=a.onLose;var p=0,lives=3,alive=true,cross=0,frame=0;var cars=[[],[],[],[]],carS=[1.5,2.5,1.8,3],carC=['#e74c3c','#3498db','#2ecc71','#f39c12'];c.innerHTML='<div style="padding:8px;text-align:center;color:#fff"><div style="font-size:14px;margin-bottom:4px">🐸 Jump across traffic! ↑ to hop, avoid cars! 3 crossings.</div><div style="font-size:12px;color:#888">Lives: <span id="fr-l">3</span> Crossings: <span id="fr-c">0</span>/3</div><canvas id="fr-cv" width="260" height="200" style="background:#0d0d1a;border-radius:8px;border:1px solid #333"></canvas></div>';var cv=c.querySelector('#fr-cv'),ctx=cv.getContext('2d'),le=c.querySelector('#fr-l'),ce=c.querySelector('#fr-c');function fy(v){return 185-v*40}function draw(){ctx.clearRect(0,0,260,200);for(var i=0;i<4;i++){ctx.fillStyle=i%2?'#1a2a1a':'#2a1a1a';ctx.fillRect(0,i*50,260,50);ctx.strokeStyle='#555';ctx.lineWidth=1;ctx.strokeRect(0,i*50,260,50)}cars.forEach(function(lane,i){lane.forEach(function(car){ctx.fillStyle=carC[i];ctx.fillRect(car.x,i*50+5,28,40);ctx.fillStyle='#fff';ctx.font='18px sans-serif';ctx.textAlign='center';ctx.fillText(car.dir>0?'→':'←',car.x+14,i*50+30)})});ctx.fillStyle='#22c55e';ctx.font='28px sans-serif';ctx.textAlign='center';ctx.fillText('🐸',130,fy(p))}document.addEventListener('keydown',function(e){if(!alive||e.key!=='ArrowUp')return;e.preventDefault();if(p>=4)return;var li=3-p;for(var i=0;i<cars[li].length;i++){var c2=cars[li][i];if(Math.abs(c2.x+14-130)<22){lives--;le.textContent=lives;if(lives<=0){alive=false;l()}return}}p++;if(p>=4){cross++;ce.textContent=cross;p=0;if(cross>=3){alive=false;w()}}draw()});setInterval(function(){if(!alive)return;frame++;for(var i=0;i<4;i++)if(frame%Math.max(8,28-Math.floor(carS[i]*5))===0)cars[i].push({x:Math.random()>0.5?-28:288,dir:Math.random()>0.5?1:-1});cars.forEach(function(lane,i){lane.forEach(function(car,j){car.x+=car.dir*carS[i];if(car.x<-30||car.x>300)lane.splice(j,1)})});draw()},40);draw()};

