G.breakout=function(container,_a){var onWin=_a.onWin,onLose=_a.onLose;container.innerHTML='<div style="padding:8px;text-align:center;color:#fff"><div style="font-size:14px;margin-bottom:4px">Move ← → with arrow keys. Break all bricks!</div><canvas id="br-canvas" width="280" height="200" style="background:#0d0d1a;border-radius:8px;border:1px solid #333"></canvas></div>';var cv=container.querySelector('#br-canvas'),ctx=cv.getContext('2d');var paddle={x:110,w:60},ball={x:140,y:180,dx:2,dy:-2,r:4};var bricks=[];for(var i=0;i<25;i++)bricks.push({x:i%5*56+2,y:Math.floor(i/5)*16+5,w:52,h:12,alive:true});var alive=true,kb={};function update(){if(!alive)return;paddle.x+=kb[37]?-4:kb[39]?4:0;paddle.x=Math.max(0,Math.min(280-paddle.w,paddle.x));ball.x+=ball.dx;ball.y+=ball.dy;if(ball.x<0||ball.x>280)ball.dx*=-1;if(ball.y<0)ball.dy*=-1;if(ball.y>200){alive=false;onLose();return}if(ball.y+ball.dy>=190-ball.r&&ball.y+ball.dy<200&&ball.x>paddle.x&&ball.x<paddle.x+paddle.w){ball.dy=-Math.abs(ball.dy);ball.y=186}bricks.forEach(function(b){if(!b.alive||ball.x<b.x||ball.x>b.x+b.w||ball.y<b.y||ball.y>b.y+b.h)return;b.alive=false;ball.dy*=-1;if(!bricks.some(function(b2){return b2.alive})){alive=false;onWin()}});draw();requestAnimationFrame(update)}function draw(){ctx.clearRect(0,0,280,200);ctx.fillStyle='#fff';ctx.fillRect(paddle.x,190,paddle.w,6);ctx.beginPath();ctx.arc(ball.x,ball.y,ball.r,0,Math.PI*2);ctx.fillStyle='#ffd700';ctx.fill();bricks.forEach(function(b){if(b.alive){ctx.fillStyle='#f44';ctx.fillRect(b.x,b.y,b.w,b.h)}})}document.addEventListener('keydown',function(e){kb[e.keyCode]=true});document.addEventListener('keyup',function(e){kb[e.keyCode]=false});update()};

