G.snake=function(container,_a){var onWin=_a.onWin,onLose=_a.onLose;var GRID=15,CELL=18;var snake=[{x:7,y:7}],dir={x:1,y:0},food={x:5,y:5},alive=true,kb={};container.innerHTML='<div style="padding:8px;text-align:center;color:#fff"><div style="font-size:14px;margin-bottom:4px">Arrow keys to move. Eat 10 food!</div><canvas id="sn-canvas" width="'+GRID*CELL+'" height="'+GRID*CELL+'" style="background:#0d0d1a;border-radius:8px;border:1px solid #333"></canvas><div style="margin-top:4px;font-size:12px;color:#888">Length: <span id="sn-len">1</span>/10</div></div>';var cv=container.querySelector('#sn-canvas'),ctx=cv.getContext('2d'),lenEl=container.querySelector('#sn-len');function update(){if(!alive)return;var nx=snake[0].x+dir.x,ny=snake[0].y+dir.y;if(nx<0||nx>=GRID||ny<0||ny>=GRID){alive=false;onLose();return}for(var i=0;i<snake.length;i++){if(snake[i].x===nx&&snake[i].y===ny){alive=false;onLose();return}}snake.unshift({x:nx,y:ny});if(nx===food.x&&ny===food.y){if(snake.length>=10){alive=false;onWin();return}food={x:Math.floor(Math.random()*GRID),y:Math.floor(Math.random()*GRID)};lenEl.textContent=snake.length}else{snake.pop()}draw()}function draw(){ctx.clearRect(0,0,GRID*CELL,GRID*CELL);ctx.fillStyle='#22c55e';snake.forEach(function(s,i){ctx.fillRect(s.x*CELL+1,s.y*CELL+1,CELL-2,CELL-2)});ctx.fillStyle='#f44';ctx.fillRect(food.x*CELL+1,food.y*CELL+1,CELL-2,CELL-2)}document.addEventListener('keydown',function(e){var k=e.key;if(k==='ArrowUp'&&dir.y!==1){dir={x:0,y:-1};e.preventDefault()}else if(k==='ArrowDown'&&dir.y!==-1){dir={x:0,y:1};e.preventDefault()}else if(k==='ArrowLeft'&&dir.x!==1){dir={x:-1,y:0};e.preventDefault()}else if(k==='ArrowRight'&&dir.x!==-1){dir={x:1,y:0};e.preventDefault()}});setInterval(update,200);draw()};

// --- Sudoku ---
G.sudoku=function(container,_a){var onWin=_a.onWin,onLose=_a.onLose;var puzzle=[[5,3,0,0,7,0,0,0,0],[6,0,0,1,9,5,0,0,0],[0,9,8,0,0,0,0,6,0],[8,0,0,0,6,0,0,0,3],[4,0,0,8,0,3,0,0,1],[7,0,0,0,2,0,0,0,6],[0,6,0,0,0,0,2,8,0],[0,0,0,4,1,9,0,0,5],[0,0,0,0,8,0,0,7,9]],solution=[[5,3,4,6,7,8,9,1,2],[6,7,2,1,9,5,3,4,8],[1,9,8,3,4,2,5,6,7],[8,5,9,7,6,1,4,2,3],[4,2,6,8,5,3,7,9,1],[7,1,3,9,2,4,8,5,6],[9,6,1,5,3,7,2,8,4],[2,8,7,4,1,9,6,3,5],[3,4,5,2,8,6,1,7,9]];container.innerHTML='<div style="padding:8px;text-align:center;color:#fff"><div style="font-size:14px;margin-bottom:8px">Fill the empty cells (0). 3 mistakes max.</div><div id="sd-grid" style="display:grid;grid-template-columns:repeat(9,32px);gap:1px;justify-content:center"></div><div id="sd-msg" style="margin-top:8px;font-size:12px;color:#888">Mistakes: 0/3</div></div>';var grid=container.querySelector('#sd-grid'),msg=container.querySelector('#sd-msg');var mistakes=0;for(var i=0;i<9;i++){for(var j=0;j<9;j++){var c=document.createElement('input');c.style.cssText='width:32px;height:32px;text-align:center;font-size:14px;background:'+(puzzle[i][j]?'#2a2a3e':'#1a1a2e')+';border:1px solid '+(j%3===2&&j<8?'#666':j%3===0?'#666':'#333')+';color:#fff;outline:none';c.value=puzzle[i][j]||'';c.readOnly=!!puzzle[i][j];c.maxLength=1;c.dataset.row=i;c.dataset.col=j;if(!puzzle[i][j]){c.addEventListener('input',function(){var r=parseInt(this.dataset.row),co=parseInt(this.dataset.col);var v=parseInt(this.value)||0;if(v<1||v>9){this.value='';return}if(v!==solution[r][co]){mistakes++;msg.textContent='Mistakes: '+mistakes+'/3';this.style.background='#3a1a1a';if(mistakes>=3)onLose()}else{this.style.background='#1a3a1a';this.readOnly=true;var done=true;document.querySelectorAll('#sd-grid input').forEach(function(inp){if(!inp.readOnly&&!inp.value)done=false});if(done){setTimeout(onWin,300)}}})}grid.appendChild(c)}}};

