G.memory_match=function(container,_a){var onWin=_a.onWin,onLose=_a.onLose;var icons=['🐱','🐶','🐰','🐼','🐸','🦊','🐯','🐷'];var deck=[...icons,...icons].sort(function(){return Math.random()-.5});var flipped=[],matched=0,pairs=icons.length;container.innerHTML='<div style="padding:8px;text-align:center"><div style="display:grid;grid-template-columns:repeat(4,60px);gap:6px;justify-content:center;margin:0 auto" id="mm-grid"></div><div style="margin-top:8px;font-size:14px;color:#888;text-align:center">Match all pairs!</div></div>';var grid=container.querySelector('#mm-grid');deck.forEach(function(icon,i){var el=document.createElement('div');el.style.cssText='width:60px;height:60px;background:#1a1a2e;border:2px solid #555;border-radius:8px;display:flex;align-items:center;justify-content:center;font-size:24px;cursor:pointer;color:#fff;';el.dataset.idx=i;el.addEventListener('click',function(){var idx=parseInt(this.dataset.idx);if(flipped.length===2)return;if(this.textContent)return;this.textContent=deck[idx];flipped.push(idx);if(flipped.length===2){var a=flipped[0],b=flipped[1];if(deck[a]===deck[b]){matched++;flipped=[];if(matched===pairs)onWin()}else{var self=this;setTimeout(function(){grid.children[a].textContent='';grid.children[b].textContent='';flipped=[]},800)}}});grid.appendChild(el)})};

// --- Reaction Test (FIXED: easier thresholds) ---
G.reaction_test=function(container,_a){var onWin=_a.onWin,onLose=_a.onLose;var state='waiting',start=0,r=0,good=0,alive=true;container.innerHTML='<div style="padding:16px;text-align:center;color:#fff"><div style="font-size:48px;margin:16px" id="rt-icon">🔴</div><div style="font-size:18px;margin:8px" id="rt-text">Wait for green...</div><div style="font-size:14px;color:#888" id="rt-status">Round 1/5</div></div>';var icon=container.querySelector('#rt-icon'),text=container.querySelector('#rt-text'),st=container.querySelector('#rt-status');function nr(){r++;if(r>5){alive=false;if(good>=3)onWin();else onLose();return}state='waiting';icon.textContent='🔴';text.textContent='Wait for green...';st.textContent='Round '+r+'/5 (won '+good+')';var delay=1000+Math.random()*2000;setTimeout(function(){if(!alive)return;state='ready';icon.textContent='🟢';text.textContent='CLICK NOW!';start=Date.now()},delay)}nr();container.addEventListener('click',function handler(){if(!alive)return;if(state==='waiting'){alive=false;onLose()}else if(state==='ready'){var time=Date.now()-start;if(time<1000){good++;nr()}else{alive=false;onLose()}}})};

