G.typing_gauntlet=function(container,_a){var onWin=_a.onWin,onLose=_a.onLose;var words=['extraordinary','incomprehensible','unprecedented','revolutionary','transcendental','phenomenological','quintessential','idiosyncratic','ineffable','supercalifragilisticexpialidocious'];var idx=0,hits=0;container.innerHTML='<div style="padding:16px;text-align:center;color:#fff"><div style="font-size:24px;margin:16px;font-family:monospace" id="tg-word">'+words[0]+'</div><div style="font-size:14px;color:#888">Type the word above and press Enter</div><input id="tg-input" style="margin-top:8px;padding:8px 16px;font-size:18px;background:#1a1a2e;border:2px solid #555;border-radius:8px;color:#fff;outline:none;text-align:center;font-family:monospace"><div style="margin-top:8px;font-size:14px;color:#888">Score: <span id="tg-score">0</span>/3</div></div>';var input=container.querySelector('#tg-input'),wordEl=container.querySelector('#tg-word'),scoreEl=container.querySelector('#tg-score');input.focus();input.addEventListener('keydown',function(e){if(e.key!=='Enter')return;if(input.value.trim()===words[idx]){hits++;scoreEl.textContent=hits;if(hits>=3){onWin();return}idx++;wordEl.textContent=words[idx];input.value=''}else{input.value='';input.focus()}})};

