function makeTarget(name,goal,emoji,label,time){G[name]=function(container,_a){var onWin=_a.onWin,onLose=_a.onLose;var score=0,remaining=time,alive=true;container.innerHTML='<div style="padding:16px;text-align:center;color:#fff"><div style="font-size:16px;margin:8px">'+label+'</div><div id="'+name+'-area" style="height:180px;background:#0d0d1a;border-radius:8px;position:relative;overflow:hidden;margin:8px 0;border:1px solid #333"></div><div style="font-size:14px;color:#888">Score: <span id="'+name+'-s">0</span>/'+goal+' | Time: <span id="'+name+'-t">'+time+'</span>s</div></div>';var area=container.querySelector('#'+name+'-area'),sEl=container.querySelector('#'+name+'-s'),tEl=container.querySelector('#'+name+'-t');function spawn(){if(!alive)return;area.innerHTML='';var t=document.createElement('div');t.textContent=emoji;t.style.cssText='position:absolute;font-size:32px;cursor:pointer;left:'+(Math.random()*240)+'px;top:'+(Math.random()*140)+'px;transition:all .3s';t.addEventListener('click',function(){score++;sEl.textContent=score;if(score>=goal){alive=false;onWin()}else spawn()});area.appendChild(t)}spawn();var iv=setInterval(function(){remaining--;tEl.textContent=remaining;if(remaining<=0){alive=false;clearInterval(iv);if(score<goal)onLose()}},1000)}}
