G.stack_the_blocks=function(c,a){var w=a.onWin,l=a.onLose;var s=0,alive=true,bx=60,bdir=1,bw=70,stacked=[],iv;c.innerHTML='<div style="padding:8px;text-align:center;color:#fff"><div style="font-size:14px;margin-bottom:4px">🧱 Click to drop the block! Align on the stack. Block shrinks each layer. 10 blocks!</div><canvas id="st-cv" width="220" height="200" style="background:#0d0d1a;border-radius:8px;border:1px solid #333"></canvas><div style="margin-top:4px;font-size:12px;color:#888">Stack: <span id="st-s">0</span>/10 | Last: <span id="st-o">-</span></div></div>';var cv=c.querySelector("#st-cv"),ctx=cv.getContext("2d"),se=c.querySelector("#st-s"),oe=c.querySelector("#st-o");function draw(){ctx.clearRect(0,0,220,200);for(var i=0;i<stacked.length;i++){ctx.fillStyle="#ffd700";ctx.fillRect(stacked[i],190-i*16,stacked.length>0?bw:70,14);ctx.strokeStyle="#b8860b";ctx.strokeRect(stacked[i],190-i*16,stacked.length>0?bw:70,14)}ctx.fillStyle="#ef4444";ctx.fillRect(bx,190-stacked.length*16-14,bw,14);ctx.strokeStyle="#555";ctx.strokeRect(0,0,220,200)}cv.addEventListener("click",function(){if(!alive)return;if(stacked.length===0){var diff=Math.abs(bx-75);if(diff<12){stacked.push(bx);s++;se.textContent=s;if(s>=10){alive=false;w()}return}alive=false;l();return}var prev=stacked[stacked.length-1];var diff=Math.abs(bx-prev);var overlap=bw-diff;if(overlap<6||bw<8){alive=false;l();return}var newBx=Math.min(bx,prev);bw=Math.max(8,overlap-2);stacked.push(newBx);s++;se.textContent=s;oe.textContent=overlap+"px";if(s>=10){alive=false;w()}});iv=setInterval(function(){if(!alive)return clearInterval(iv);bx+=bdir*3;if(bx<0||bx+bw>220)bdir*=-1;draw()},30)};

G.tower_builder=function(c,a){var w=a.onWin,l=a.onLose;var s=0,alive=true,bx=80,bdir=1,falling=false,fy=0,iv,prevX=80;c.innerHTML='<div style="padding:8px;text-align:center;color:#fff"><div style="font-size:14px;margin-bottom:4px">🏗️ Click to place! Blocks fall from above. Catch 12 to build your tower!</div><canvas id="tb-cv" width="220" height="200" style="background:#0d0d1a;border-radius:8px;border:1px solid #333"></canvas><div style="margin-top:4px;font-size:12px;color:#888">Blocks: <span id="tb-s">0</span>/12 | Platform: ← → keys</div></div>';var cv=c.querySelector("#tb-cv"),ctx=cv.getContext("2d"),se=c.querySelector("#tb-s");function draw(){ctx.clearRect(0,0,220,200);ctx.fillStyle="#8B4513";ctx.fillRect(prevX-35,190,70,10);ctx.fillStyle="#e67e22";if(falling)ctx.fillRect(bx,fy,30,16);else ctx.fillRect(bx,8,30,16)}cv.addEventListener("click",function(){if(!alive||falling)return;falling=true;fy=24;bx=bx;var fallIv=setInterval(function(){fy+=4;if(fy>=180){clearInterval(fallIv);falling=false;var diff=Math.abs(bx+15-(prevX));if(diff<25){s++;se.textContent=s;prevX=bx+15;if(s>=12){alive=false;w()}}else{alive=false;l()}}},30)});document.addEventListener("keydown",function(e){if(alive&&!falling){if(e.key==="ArrowLeft")bx=Math.max(0,bx-15);if(e.key==="ArrowRight")bx=Math.min(190,bx+15)}});iv=setInterval(function(){if(!alive)return clearInterval(iv);draw()},30)};

