function makeDodge(name,emoji,label,time,goal){G[name]=function(container,_a){var onWin=_a.onWin,onLose=_a.onLose;var survived=0,alive=true;container.innerHTML='<div style="padding:16px;text-align:center;color:#fff"><div style="font-size:36px">'+emoji+'</div><div style="font-size:16px;margin:8px">'+label+'</div><div style="height:160px;background:#0d0d1a;border-radius:8px;position:relative;overflow:hidden;margin:8px 0;border:1px solid #333" id="'+name+'-area"><div id="'+name+'-player" style="position:absolute;bottom:10px;left:120px;font-size:24px;transition:left .15s">🧑</div></div><div style="font-size:14px;color:#888">Survived: <span id="'+name+'-s">0</span>s'+(goal?'/'+goal:'')+'</div></div>';var area=container.querySelector('#'+name+'-area'),player=container.querySelector('#'+name+'-player'),sEl=container.querySelector('#'+name+'-s');var danger=[],iv,loop,playerX=120;function spawnDanger(){if(!alive)return;var leftPos=Math.random()*250;var d=document.createElement('div');d.textContent=emoji;d.style.cssText='position:absolute;top:-20px;left:'+leftPos+'px;font-size:20px;transition:top '+(time||3)+'s linear';area.appendChild(d);d.dangerLeft=leftPos;danger.push(d);setTimeout(function(){d.style.top='160px'},50);setTimeout(function(){if(d.parentNode&&alive){var dLeft=parseFloat(d.style.left);var dRight=dLeft+20;var pLeft=playerX;var pRight=pLeft+24;if(dRight>pLeft&&dLeft<pRight){alive=false;onLose()}}},(time||3)*1000)}document.addEventListener('keydown',function handler(e){if(!alive)return;var k=e.key;var left=parseInt(player.style.left)||120;if(k==='ArrowLeft'||k==='a')player.style.left=Math.max(0,left-25)+'px';else if(k==='ArrowRight'||k==='d')player.style.left=Math.min(260,left+25)+'px';playerX=parseInt(player.style.left)||120});iv=setInterval(function(){if(!alive)return;survived++;sEl.textContent=survived;if(goal&&survived>=goal){alive=false;clearInterval(iv);clearInterval(loop);onWin()}},1000);loop=setInterval(spawnDanger,Math.max(500,3000/time||2000))}}
