G.geometry_dash_runner=function(container,_a){var onWin=_a.onWin,onLose=_a.onLose;var pos=100,alive=true,obstacles=[],frame=0;container.innerHTML='<div style="padding:8px;text-align:center;color:#fff"><div style="font-size:14px;margin-bottom:4px">Jump with SPACE or click! Pass 8 obstacles.</div><canvas id="gd-canvas" width="280" height="200" style="background:#0d0d1a;border-radius:8px;border:1px solid #333"></canvas><div style="margin-top:4px;font-size:12px;color:#888">Score: <span id="gd-s">0</span>/8</div></div>';var cv=container.querySelector('#gd-canvas'),ctx=cv.getContext('2d'),sEl=container.querySelector('#gd-s');var vy=0,score=0;function update(){if(!alive)return;vy+=0.5;pos+=vy;if(pos>180){pos=180;vy=0}frame++;if(frame%40===0){obstacles.push({x:280,w:15+Math.random()*15})}for(var i=obstacles.length-1;i>=0;i--){var o=obstacles[i];o.x-=4;if(o.x<40&&o.x+o.w>20&&pos>140){alive=false;onLose()}if(o.x<-30){if(!o.passed){o.passed=true;score++;sEl.textContent=score;if(score>=8){alive=false;onWin()}}obstacles.splice(i,1)}}draw();requestAnimationFrame(update)}function draw(){ctx.clearRect(0,0,280,200);ctx.fillStyle='#22c55e';ctx.fillRect(20,pos,20,20);ctx.fillStyle='#f44';obstacles.forEach(function(o){ctx.fillRect(o.x,140,o.w,60)})}document.addEventListener('keydown',function(e){if((e.key===' '||e.key==='ArrowUp')&&pos>=170){vy=-10;e.preventDefault()}});container.addEventListener('click',function(){if(pos>=170)vy=-10});update()};

G.wall_jump_escape=function(container,_a){var onWin=_a.onWin,onLose=_a.onLose;var pos=150,alive=true,frame=0;container.innerHTML='<div style="padding:8px;text-align:center;color:#fff"><div style="font-size:14px;margin-bottom:4px">Click/SPACE to jump! Climb 5 walls.</div><canvas id="wj-canvas" width="280" height="200" style="background:#0d0d1a;border-radius:8px;border:1px solid #333"></canvas><div style="margin-top:4px;font-size:12px;color:#888">Walls: <span id="wj-s">0</span>/5</div></div>';var cv=container.querySelector('#wj-canvas'),ctx=cv.getContext('2d'),sEl=container.querySelector('#wj-s');var vy=0,score=0,walls=[];function update(){if(!alive)return;vy+=0.5;pos+=vy;if(pos>180){pos=180;vy=0}frame++;if(frame%60===0){walls.push({x:280,gap:50+Math.random()*60})}for(var i=walls.length-1;i>=0;i--){var w=walls[i];w.x-=3;if(w.x<40&&w.x+20>20&&(pos<w.gap||pos>w.gap+30)){alive=false;onLose()}if(w.x<-30){if(!w.passed){w.passed=true;score++;sEl.textContent=score;if(score>=5){alive=false;onWin()}}walls.splice(i,1)}}draw();requestAnimationFrame(update)}function draw(){ctx.clearRect(0,0,280,200);ctx.fillStyle='#ffd700';ctx.fillRect(20,pos,20,20);ctx.fillStyle='#888';walls.forEach(function(w){ctx.fillRect(w.x,0,20,w.gap);ctx.fillRect(w.x,w.gap+30,20,200-w.gap-30)})}document.addEventListener('keydown',function(e){if((e.key===' '||e.key==='ArrowUp')&&pos>=170){vy=-10;e.preventDefault()}});container.addEventListener('click',function(){if(pos>=170)vy=-10});update()};

G.obstacle_dash=function(container,_a){var onWin=_a.onWin,onLose=_a.onLose;var px=140,alive=true;container.innerHTML='<div style="padding:8px;text-align:center;color:#fff"><div style="font-size:14px;margin-bottom:4px">Use ← → to dodge! Survive 10 obstacles.</div><canvas id="od-canvas" width="280" height="200" style="background:#0d0d1a;border-radius:8px;border:1px solid #333"></canvas><div style="margin-top:4px;font-size:12px;color:#888">Dodged: <span id="od-s">0</span>/10</div></div>';var cv=container.querySelector('#od-canvas'),ctx=cv.getContext('2d'),sEl=container.querySelector('#od-s');var obs=[],score=0,frame=0;function update(){if(!alive)return;frame++;if(frame%30===0){obs.push({x:Math.random()*260,y:0,w:20,h:20,dodged:false})}for(var i=obs.length-1;i>=0;i--){var o=obs[i];o.y+=3;if(o.y>200){if(!o.dodged){o.dodged=true;score++;sEl.textContent=Math.min(score,10);if(score>=10){alive=false;onWin()}}obs.splice(i,1)}}obs.forEach(function(o){if(Math.abs(o.x+10-px-10)<20&&o.y+20>180){alive=false;onLose()}});draw();requestAnimationFrame(update)}function draw(){ctx.clearRect(0,0,280,200);ctx.fillStyle='#22c55e';ctx.fillRect(px,180,20,20);ctx.fillStyle='#f44';obs.forEach(function(o){ctx.fillRect(o.x,o.y,o.w,o.h)})}document.addEventListener('keydown',function(e){if(e.key==='ArrowLeft')px=Math.max(0,px-20);if(e.key==='ArrowRight')px=Math.min(260,px+20)});update()};

G.platform_parkour=function(container,_a){var onWin=_a.onWin,onLose=_a.onLose;var px=30,vy=0,alive=true,frame=0,score=0;container.innerHTML='<div style="padding:8px;text-align:center;color:#fff"><div style="font-size:14px;margin-bottom:4px">SPACE/Click to jump! Cross 6 platforms.</div><canvas id="pp-canvas" width="280" height="200" style="background:#0d0d1a;border-radius:8px;border:1px solid #333"></canvas><div style="margin-top:4px;font-size:12px;color:#888">Platforms: <span id="pp-s">0</span>/6</div></div>';var cv=container.querySelector('#pp-canvas'),ctx=cv.getContext('2d'),sEl=container.querySelector('#pp-s');var plats=[];for(var i=0;i<6;i++)plats.push({x:30+i*45,y:140-Math.random()*30,w:40,h:8});var py=plats[0].y-20;function update(){if(!alive)return;vy+=0.5;py+=vy;px+=2;if(py>195){alive=false;onLose();return}var on=false;plats.forEach(function(p){if(px>p.x-15&&px<p.x+p.w+15&&py>=p.y-20&&py<=p.y&&vy>0){py=p.y-20;vy=0;on=true}});frame++;score=plats.filter(function(p){return px>p.x+p.w}).length;sEl.textContent=Math.min(score,6);if(score>=6){alive=false;onWin()}draw();requestAnimationFrame(update)}function draw(){ctx.clearRect(0,0,280,200);ctx.fillStyle='#22c55e';ctx.fillRect(px,py,15,20);ctx.fillStyle='#8B4513';plats.forEach(function(p){ctx.fillRect(p.x,p.y,p.w,p.h)})}document.addEventListener('keydown',function(e){if((e.key===' '||e.key==='ArrowUp')&&vy===0){vy=-10;e.preventDefault()}});container.addEventListener('click',function(){if(vy===0)vy=-10});update()};

G.jetpack_flight=function(container,_a){var onWin=_a.onWin,onLose=_a.onLose;var y=100,vy=0,alive=true,score=0;container.innerHTML='<div style="padding:8px;text-align:center;color:#fff"><div style="font-size:14px;margin-bottom:4px">Hold SPACE/Click to fly! Pass 8 obstacles.</div><canvas id="jf-canvas" width="280" height="200" style="background:#0d0d1a;border-radius:8px;border:1px solid #333"></canvas><div style="margin-top:4px;font-size:12px;color:#888">Score: <span id="jf-s">0</span>/8</div></div>';var cv=container.querySelector('#jf-canvas'),ctx=cv.getContext('2d'),sEl=container.querySelector('#jf-s');var obs=[],frame=0,flying=false;function update(){if(!alive)return;vy+=flying?-0.5:0.5;y+=vy;y=Math.max(5,Math.min(180,y));frame++;if(frame%35===0){var gap=40+Math.random()*40,topY=Math.random()*60;obs.push({x:280,top:topY,bottom:topY+gap})}for(var i=obs.length-1;i>=0;i--){var o=obs[i];o.x-=3;if(o.x<-30)obs.splice(i,1)}obs.forEach(function(o){if(o.x<30&&o.x+15>10&&(y<o.top||y>o.bottom)){alive=false;onLose()}});if(obs.length&&obs[0].x<-15&&obs[0].passed!==true){obs[0].passed=true;score++;sEl.textContent=score;if(score>=8){alive=false;onWin()}}draw();requestAnimationFrame(update)}function draw(){ctx.clearRect(0,0,280,200);ctx.fillStyle='#ffd700';ctx.fillRect(15,y,15,15);ctx.fillStyle='#f44';obs.forEach(function(o){ctx.fillRect(o.x,0,15,o.top);ctx.fillRect(o.x,o.bottom,15,200-o.bottom)})}document.addEventListener('keydown',function(e){if(e.key===' '||e.key==='ArrowUp'){flying=true;e.preventDefault()}});document.addEventListener('keyup',function(e){if(e.key===' '||e.key==='ArrowUp')flying=false});container.addEventListener('mousedown',function(){flying=true});container.addEventListener('mouseup',function(){flying=false});update()};

G.rocket_dodger=function(container,_a){var onWin=_a.onWin,onLose=_a.onLose;var y=100,alive=true,score=0;container.innerHTML='<div style="padding:8px;text-align:center;color:#fff"><div style="font-size:14px;margin-bottom:4px">Click to move! Dodge 10 rockets.</div><canvas id="rd-canvas" width="280" height="200" style="background:#0d0d1a;border-radius:8px;border:1px solid #333"></canvas><div style="margin-top:4px;font-size:12px;color:#888">Dodged: <span id="rd-s">0</span>/10</div></div>';var cv=container.querySelector('#rd-canvas'),ctx=cv.getContext('2d'),sEl=container.querySelector('#rd-s');var rks=[],frame=0;function update(){if(!alive)return;frame++;if(frame%25===0){rks.push({x:280,y:Math.random()*180})}for(var i=rks.length-1;i>=0;i--){var r=rks[i];r.x-=5;if(r.x<-20)rks.splice(i,1)}rks.forEach(function(r){if(Math.abs(r.x-20)<15&&Math.abs(r.y-y)<15){alive=false;onLose()}});score=Math.floor(frame/50);sEl.textContent=Math.min(score,10);if(score>=10){alive=false;onWin()}draw();requestAnimationFrame(update)}function draw(){ctx.clearRect(0,0,280,200);ctx.fillStyle='#22c55e';ctx.beginPath();ctx.arc(20,y,10,0,Math.PI*2);ctx.fill();ctx.fillStyle='#f44';rks.forEach(function(r){ctx.fillRect(r.x,r.y,15,5)})}container.addEventListener('mousemove',function(e){var rect=cv.getBoundingClientRect();y=e.clientY-rect.top});update()};

G.ice_slide_puzzle=function(c,a){var w=a.onWin,l=a.onLose;var S=5,px=0,py=0,gx=4,gy=4,alive=true,moves=0;var walls=new Set();for(var i=0;i<4;i++){var wi;do{wi=Math.floor(Math.random()*S*S)}while(wi===0||wi===S*S-1||wi===1||wi===S||wi===S*S-2||wi===S*S-1-S||walls.has(wi));walls.add(wi)}c.innerHTML='<div style="padding:8px;text-align:center;color:#fff"><div style="font-size:14px;margin-bottom:4px">❄️ Ice slide! Slide until you hit a wall. Reach ★ 3 times.</div><canvas id="is-cv" width="250" height="250" style="background:#0d0d1a;border-radius:8px;border:1px solid #333"></canvas><div style="margin-top:4px;font-size:12px;color:#888">Moves: <span id="is-m">0</span> | Wins: <span id="is-w">0</span>/3</div></div>';var cv=c.querySelector("#is-cv"),ctx=cv.getContext("2d"),mEl=c.querySelector("#is-m"),wEl=c.querySelector("#is-w");var CL=50,wins=0;function draw(){ctx.clearRect(0,0,250,250);for(var y=0;y<S;y++)for(var x=0;x<S;x++){var idx=y*S+x;if(walls.has(idx)){ctx.fillStyle="#555";ctx.fillRect(x*CL,y*CL,CL,CL);ctx.strokeStyle="#444";ctx.strokeRect(x*CL,y*CL,CL,CL)}else if(x===gx&&y===gy){ctx.fillStyle="#22c55e";ctx.fillRect(x*CL+1,y*CL+1,CL-2,CL-2);ctx.fillStyle="#fff";ctx.font="18px sans-serif";ctx.textAlign="center";ctx.textBaseline="middle";ctx.fillText("★",x*CL+CL/2,y*CL+CL/2)}else{ctx.fillStyle="#0d0d1a";ctx.fillRect(x*CL,y*CL,CL,CL);ctx.strokeStyle="#222";ctx.strokeRect(x*CL,y*CL,CL,CL)}}ctx.fillStyle="#ffd700";ctx.beginPath();ctx.arc(px*CL+CL/2,py*CL+CL/2,14,0,Math.PI*2);ctx.fill();ctx.fillStyle="#333";ctx.fillRect(px*CL+CL/2-5,py*CL+CL/2-5,10,10)}document.addEventListener("keydown",function(e){if(!alive)return;var dx=0,dy=0;if(e.key==="ArrowRight")dx=1;else if(e.key==="ArrowLeft")dx=-1;else if(e.key==="ArrowDown")dy=1;else if(e.key==="ArrowUp")dy=-1;else return;e.preventDefault();var nx=px,ny=py;while(true){var nnx=nx+dx,nny=ny+dy;if(nnx<0||nnx>=S||nny<0||nny>=S||walls.has(nny*S+nnx))break;nx=nnx;ny=nny}if(nx===px&&ny===py)return;px=nx;py=ny;moves++;mEl.textContent=moves;if(px===gx&&py===gy){wins++;wEl.textContent=wins;if(wins>=3){alive=false;w();return}px=0;py=0;walls.clear();for(var j=0;j<4;j++){var wj;do{wj=Math.floor(Math.random()*S*S)}while(wj===0||wj===S*S-1||wj===1||wj===S||wj===S*S-2||wj===S*S-1-S||walls.has(wj));walls.add(wj)}}draw()});draw()};

G.grappling_hook_swing=function(c,a){var w=a.onWin,l=a.onLose;var dist=0,alive=true,angle=0,adir=1,iv;c.innerHTML='<div style="padding:16px;text-align:center;color:#fff"><div style="font-size:14px;margin-bottom:4px">🪝 Pendulum swings! Click to release the hook! Land on platforms. 80m total!</div><div style="font-size:14px;color:#888">Distance: <span id="gr-d">0</span>/80m</div><canvas id="gr-cv" width="240" height="140" style="background:#0d0d1a;border-radius:8px;border:1px solid #333"></canvas></div>';var cv=c.querySelector("#gr-cv"),ctx=cv.getContext("2d"),de=c.querySelector("#gr-d");var cx=120,cy=30,ropeLen=90,px2=120,py2=120,swinging=true;function draw(){ctx.clearRect(0,0,240,140);ctx.strokeStyle="#888";ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(cx,cy);var endX=cx+Math.sin(angle)*ropeLen,endY=cy+Math.cos(angle)*ropeLen;ctx.lineTo(endX,endY);ctx.stroke();ctx.fillStyle="#22c55e";ctx.beginPath();ctx.arc(endX,endY,10,0,Math.PI*2);ctx.fill();ctx.fillStyle="#8B4513";ctx.fillRect(0,130,240,10);ctx.fillStyle="#ffd700";ctx.fillRect(dist/80*220,125,15,8)}cv.addEventListener("click",function(){if(!alive||!swinging)return;swinging=false;var endX=cx+Math.sin(angle)*ropeLen;var landed=endX>dist/80*220-5&&endX<dist/80*220+30;var gain=Math.abs(Math.sin(angle))*30+5;dist+=gain;de.textContent=Math.min(Math.round(dist),80);if(dist>=80){alive=false;w();return}if(!landed){alive=false;l();return}swinging=true});iv=setInterval(function(){if(!alive)return clearInterval(iv);if(swinging){angle+=adir*0.05;if(angle>1.5||angle<-1.5)adir*=-1}draw()},30)};

// ---- ZOMBIE/ALIEN/SPACE survival games ----
function makeShooter(name,emoji,label,goal,speed){G[name]=function(container,_a){var onWin=_a.onWin,onLose=_a.onLose;var score=0,alive=true,start=Date.now(),duration=(goal*5+10)*1e3;container.innerHTML='<div style="padding:8px;text-align:center;color:#fff"><div style="font-size:14px;margin-bottom:4px">'+label+'</div><canvas id="'+name+'-cv" width="280" height="200" style="background:#0d0d1a;border-radius:8px;border:1px solid #333"></canvas><div style="margin-top:4px;font-size:12px;color:#888">Score: <span id="'+name+'-s">0</span>/'+goal+' | Time: <span id="'+name+'-t">'+((goal*5+10)/1e3)+'</span>s</div></div>';var cv=container.querySelector('#'+name+'-cv'),ctx=cv.getContext('2d'),sEl=container.querySelector('#'+name+'-s'),tEl=container.querySelector('#'+name+'-t');var enemies=[],frame=0;function update(){if(!alive)return;frame++;var elapsed=Date.now()-start,remaining=Math.max(0,Math.ceil((duration-elapsed)/1e3));if(tEl)tEl.textContent=remaining;if(elapsed>=duration){alive=false;onLose();return}if(frame%Math.max(10,30/speed||20)===0){enemies.push({x:Math.random()*260,y:0,size:15+Math.random()*10})}for(var i=enemies.length-1;i>=0;i--){var e=enemies[i];e.y+=speed||2;if(e.y>200)enemies.splice(i,1)}draw();requestAnimationFrame(update)}function draw(){ctx.clearRect(0,0,280,200);enemies.forEach(function(e){ctx.fillStyle='#f44';ctx.beginPath();ctx.arc(e.x+e.size/2,e.y+e.size/2,e.size/2,0,Math.PI*2);ctx.fill();ctx.fillStyle='#fff';ctx.font=''+(e.size)+'px sans-serif';ctx.textAlign='center';ctx.fillText(emoji,e.x+e.size/2,e.y+e.size/2+5)})}cv.addEventListener('click',function(e){if(!alive)return;var rect=cv.getBoundingClientRect();var mx=e.clientX-rect.left,my=e.clientY-rect.top;for(var i=enemies.length-1;i>=0;i--){var en=enemies[i];if(mx>en.x&&mx<en.x+en.size&&my>en.y&&my<en.y+en.size){enemies.splice(i,1);score++;sEl.textContent=score;if(score>=goal){alive=false;onWin()}return}}});update()}}
