G.angry_birds_launcher=function(c,a){var w=a.onWin,l=a.onLose;var score=0,alive=true,pwr=0,dir=1,filling=false,iv;c.innerHTML='<div style="padding:16px;text-align:center;color:#fff"><div style="font-size:14px;margin-bottom:4px">🐦 Pull back! Click Launch, click again to release! Hit 5 targets!</div><div style="font-size:14px;color:#888">Hits: <span id="ab-s">0</span>/5</div><canvas id="ab-cv" width="260" height="150" style="background:#0d0d1a;border-radius:8px;border:1px solid #333"></canvas><div style="background:#1a1a2e;border-radius:6px;height:12px;margin:4px 0;overflow:hidden;border:1px solid #555"><div id="ab-meter" style="height:12px;width:0%;background:linear-gradient(90deg,#22c55e,#e67e22,#ef4444);border-radius:6px;transition:width 0s"></div></div><button id="ab-btn" style="margin-top:4px;padding:8px 24px;background:#e67e22;border:none;border-radius:8px;color:#fff;font-size:15px;cursor:pointer">🎯 LAUNCH!</button><div id="ab-msg" style="margin-top:4px;font-size:11px;color:#888">Click LAUNCH to start power meter</div></div>';var cv=c.querySelector("#ab-cv"),ctx=cv.getContext("2d"),se=c.querySelector("#ab-s"),meter=c.querySelector("#ab-meter"),msg=c.querySelector("#ab-msg"),be=c.querySelector("#ab-btn");var targets=[];for(var ti=0;ti<5;ti++)targets.push({x:180+Math.random()*60,y:20+Math.random()*60,w:20,h:20,hit:false});function draw(){ctx.clearRect(0,0,260,150);ctx.fillStyle="#666";ctx.fillRect(0,0,260,150);targets.forEach(function(t){if(!t.hit){ctx.fillStyle="#ef4444";ctx.fillRect(t.x,t.y,t.w,t.h);ctx.fillStyle="#fff";ctx.font="12px sans-serif";ctx.fillText("🎯",t.x+3,t.y+14)}});ctx.fillStyle="#e67e22";ctx.fillRect(20,130,24,20)}be.addEventListener("click",function(){if(!alive)return;if(!filling){filling=true;msg.textContent="Click STOP to launch!";pwr=0;dir=1;be.textContent="STOP!";clearInterval(iv);iv=setInterval(function(){pwr+=dir*3;if(pwr>=100)dir=-1;if(pwr<=0)dir=1;meter.style.width=pwr+"%"},30)}else{filling=false;clearInterval(iv);be.disabled=true;var dist=pwr*2.4;var hitTarget=false;var projX=20+dist;targets.forEach(function(t){if(!t.hit&&projX>t.x-10&&projX<t.x+t.w+10){t.hit=true;score++;se.textContent=score;hitTarget=true}});draw();ctx.fillStyle="#e67e22";ctx.beginPath();ctx.arc(projX,120-dist*0.25,8,0,Math.PI*2);ctx.fill();setTimeout(function(){if(!alive)return;if(hitTarget&&score>=5){alive=false;w();return}if(!hitTarget){alive=false;l();return}be.disabled=false;be.textContent="🎯 LAUNCH!";msg.textContent="Hit! Next target!"},600)}});draw()};

G.ragdoll_launch=function(c,a){var w=a.onWin,l=a.onLose;var score=0,alive=true,filling=false,pwr=0,dir=1,iv;c.innerHTML='<div style="padding:16px;text-align:center;color:#fff"><div style="font-size:14px;margin-bottom:4px">🤸 Click Launch, click again to launch the ragdoll! Land in the green zone! 5 landings.</div><div style="font-size:14px;color:#888">Landings: <span id="rl-s">0</span>/5 | Misses: <span id="rl-m">0</span>/3</div><canvas id="rl-cv" width="260" height="120" style="background:#0d0d1a;border-radius:8px;border:1px solid #333"></canvas><div style="background:#1a1a2e;border-radius:6px;height:12px;margin:4px 0;overflow:hidden;border:1px solid #555"><div id="rl-meter" style="height:12px;width:0%;background:linear-gradient(90deg,#22c55e,#e67e22,#ef4444);border-radius:6px;transition:width 0s"></div></div><button id="rl-btn" style="margin-top:4px;padding:8px 24px;background:#3498db;border:none;border-radius:8px;color:#fff;font-size:15px;cursor:pointer">🚀 LAUNCH!</button><div id="rl-msg" style="margin-top:4px;font-size:11px;color:#888">Click LAUNCH to start power</div></div>';var cv=c.querySelector("#rl-cv"),ctx=cv.getContext("2d"),se=c.querySelector("#rl-s"),me=c.querySelector("#rl-m"),meter=c.querySelector("#rl-meter"),msg=c.querySelector("#rl-msg"),be=c.querySelector("#rl-btn");function draw(pwrd){ctx.clearRect(0,0,260,120);ctx.fillStyle="#22c55e";ctx.fillRect(90,100,80,20);ctx.fillStyle="#444";ctx.fillRect(0,100,260,20);ctx.fillStyle="#f97316";var lx=30+(pwrd||0)*1.8;ctx.beginPath();ctx.arc(lx,90,10,0,Math.PI*2);ctx.fill()};be.addEventListener("click",function(){if(!alive)return;if(!filling){filling=true;msg.textContent="Click STOP to launch!";pwr=0;dir=1;be.textContent="STOP!";clearInterval(iv);iv=setInterval(function(){pwr+=dir*3;if(pwr>=100)dir=-1;if(pwr<=0)dir=1;meter.style.width=pwr+"%";draw(pwr)},30)}else{filling=false;clearInterval(iv);be.disabled=true;var inZone=pwr>35&&pwr<70;draw(pwr);setTimeout(function(){if(inZone){score++;se.textContent=score;if(score>=5){alive=false;w();return}msg.textContent="Landed! Next launch!"}else{var miss=parseInt(me.textContent)||0;miss++;me.textContent=miss;if(miss>=3){alive=false;l();return}msg.textContent="Missed! Try again!"}be.disabled=false;be.textContent="🚀 LAUNCH!"},500)}})};

G.physics_golf=function(c,a){var w=a.onWin,l=a.onLose;var score=0,misses=0,alive=true,filling=false,pwr=0,dir=1,iv;c.innerHTML='<div style="padding:16px;text-align:center;color:#fff"><div style="font-size:14px;margin-bottom:4px">⛳ Click PUTT, click STOP to lock power! Land ball near hole. 3 wins.</div><div style="font-size:14px;color:#888">Score: <span id="pg-s">0</span>/3 | Misses: <span id="pg-m">0</span>/3</div><div style="background:#1a5a1a;border-radius:8px;height:70px;position:relative;margin:8px 0" id="pg-green"><div id="pg-ball" style="position:absolute;bottom:12px;left:15px;font-size:22px;transition:none">⚪</div><div id="pg-hole" style="position:absolute;bottom:12px;left:215px;width:24px;height:24px;background:#222;border-radius:50%"></div></div><div style="background:#1a1a2e;border-radius:6px;height:12px;margin:6px 0;overflow:hidden;border:1px solid #555"><div id="pg-meter" style="height:12px;width:0%;background:linear-gradient(90deg,#22c55e,#e67e22,#ef4444);border-radius:6px;transition:width 0s"></div></div><button id="pg-btn" style="padding:8px 24px;background:#22c55e;border:none;border-radius:8px;color:#fff;font-size:15px;cursor:pointer">PUTT</button><div id="pg-msg" style="margin-top:4px;font-size:11px;color:#888">Click PUTT to fill power meter</div></div>';var btn=c.querySelector("#pg-btn"),se=c.querySelector("#pg-s"),me=c.querySelector("#pg-m"),meter=c.querySelector("#pg-meter"),msg=c.querySelector("#pg-msg"),ball=c.querySelector("#pg-ball");btn.addEventListener("click",function(){if(!alive)return;if(!filling){filling=true;msg.textContent="Click STOP to lock power!";pwr=0;dir=1;btn.textContent="STOP!";clearInterval(iv);iv=setInterval(function(){pwr+=dir*3;if(pwr>=100)dir=-1;if(pwr<=0)dir=1;meter.style.width=pwr+"%"},30)}else{filling=false;clearInterval(iv);msg.textContent="Rolling...";btn.disabled=true;var dist=pwr*2.4;ball.style.transition="left "+(0.3+dist/200)+"s ease-out";ball.style.left=Math.min(15+dist,240)+"px";setTimeout(function(){ball.style.transition="none";var bx=15+dist;var holeX=215;if(Math.abs(bx-holeX)<25){score++;se.textContent=score;if(score>=3){alive=false;w();return}msg.textContent="Nice putt! Next hole!";ball.style.left="15px";btn.disabled=false}else{misses++;me.textContent=misses;ball.style.left="15px";if(misses>=3){alive=false;l();return}msg.textContent="Missed! Try again.";btn.disabled=false}btn.textContent="PUTT"},600)}})};

