G.endless_climber=function(c,a){var w=a.onWin,l=a.onLose;var h2=0,alive=true,px=120,frame=0;c.innerHTML='<div style="padding:8px;text-align:center;color:#fff"><div style="font-size:14px;margin-bottom:4px">🧗 ← → to dodge falling rocks! Climb 50m!</div><canvas id="ec-cv" width="260" height="200" style="background:#0d0d1a;border-radius:8px;border:1px solid #333"></canvas><div style="margin-top:4px;font-size:12px;color:#888">Height: <span id="ec-h">0</span>/50m</div></div>';var cv=c.querySelector("#ec-cv"),ctx=cv.getContext("2d"),he=c.querySelector("#ec-h");var rocks=[];document.addEventListener("keydown",function(e){if(!alive)return;if(e.key==="ArrowLeft")px=Math.max(10,px-15);if(e.key==="ArrowRight")px=Math.min(250,px+15)});function update(){if(!alive)return;frame++;if(frame%15===0)rocks.push({x:Math.random()*250,y:-10,size:8+Math.random()*12,speed:1.5+Math.random()*2.5});for(var i=rocks.length-1;i>=0;i--){var r=rocks[i];r.y+=r.speed;if(r.y>220){rocks.splice(i,1);continue}if(r.x+5<px+10&&r.x+r.size>px-10&&r.y+10>180){alive=false;l();return}}h2=Math.min(50,h2+0.1);he.textContent=Math.floor(h2);if(h2>=50){alive=false;w();return}ctx.clearRect(0,0,260,200);for(var y=0;y<200;y+=20){ctx.fillStyle=y%40===0?"#3a3a3a":"#2a2a2a";ctx.fillRect(0,y,260,20)}for(var i=0;i<rocks.length;i++){ctx.fillStyle="#888";ctx.fillRect(rocks[i].x,rocks[i].y,rocks[i].size,rocks[i].size)}ctx.fillStyle="#e67e22";ctx.fillRect(px-8,180,16,20);requestAnimationFrame(update)}update()};

G.speed_runner=function(c,a){var w=a.onWin,l=a.onLose;var dist2=0,alive=true,px2=30,frame=0,jumping=false,jy=0,jv=0,obstacles=[];c.innerHTML='<div style="padding:8px;text-align:center;color:#fff"><div style="font-size:14px;margin-bottom:4px">🏃 Click/SPACE to jump over obstacles! Run 100m!</div><canvas id="sr-cv" width="260" height="120" style="background:#0d0d1a;border-radius:8px;border:1px solid #333"></canvas><div style="margin-top:4px;font-size:12px;color:#888">Distance: <span id="sr-d">0</span>/80m</div></div>';var cv=c.querySelector("#sr-cv"),ctx=cv.getContext("2d"),de=c.querySelector("#sr-d");function jump(){if(!alive||jumping)return;jumping=true;jv=-8}document.addEventListener("keydown",function(e){if(e.key===" "||e.key==="Space"){e.preventDefault();jump()}});cv.addEventListener("click",jump);function update(){if(!alive)return;frame++;dist2+=0.3;de.textContent=Math.floor(Math.min(dist2,80));if(dist2>=80){alive=false;w();return}if(frame%40===0)obstacles.push({x:270,h:15+Math.random()*20,w:8+Math.random()*8});for(var i=obstacles.length-1;i>=0;i--){obstacles[i].x-=2.5+dist2/100;if(obstacles[i].x<-20){obstacles.splice(i,1);continue}}if(jumping){jy+=jv;jv+=0.5;if(jy>=0){jy=0;jumping=false}}for(var i=0;i<obstacles.length;i++){var o=obstacles[i];if(px2+12>o.x&&px2-12<o.x+o.w&&jy<o.h-5){alive=false;l();return}}ctx.clearRect(0,0,260,120);ctx.fillStyle="#333";ctx.fillRect(0,0,260,120);for(var i=0;i<obstacles.length;i++){ctx.fillStyle="#e67e22";ctx.fillRect(obstacles[i].x,120-obstacles[i].h,obstacles[i].w,obstacles[i].h)}ctx.fillStyle="#22c55e";ctx.fillRect(px2-10,100-jy,14,20);requestAnimationFrame(update)}update()};

G.time_attack_mode=function(c,a){var w=a.onWin,l=a.onLose;var s=0,t=15,alive=true;c.innerHTML='<div style="padding:16px;text-align:center;color:#fff"><div style="font-size:14px;margin-bottom:8px">⏰ Click popping targets! 20 hits in 15s!</div><div style="font-size:14px;color:#888">Hits: <span id="ta-c">0</span>/20 | Time: <span id="ta-t">15</span>s</div><div id="ta-a" style="position:relative;width:260px;height:160px;margin:8px auto;background:#0d0d1a;border-radius:12px;overflow:hidden"></div></div>';var a2=c.querySelector("#ta-a"),ce=c.querySelector("#ta-c"),te=c.querySelector("#ta-t");function spawn(){if(!alive)return;var t2=document.createElement("div");t2.style.cssText="position:absolute;width:36px;height:36px;background:#ef4444;border-radius:50%;cursor:pointer;display:flex;align-items:center;justify-content:center;font-size:18px;left:"+Math.floor(Math.random()*220)+"px;top:"+Math.floor(Math.random()*120)+"px";t2.textContent="🎯";t2.addEventListener("click",function cl(){s++;ce.textContent=s;a2.removeChild(t2);if(s>=20){alive=false;w()}else spawn()});a2.appendChild(t2);setTimeout(function(){if(t2.parentNode)a2.removeChild(t2)},2000)}spawn();var iv=setInterval(function(){t--;te.textContent=t;if(t<=0){alive=false;clearInterval(iv);if(s<20)l()}},1000)};

G.high_score_challenge=function(c,a){var w=a.onWin,l=a.onLose;var s=0,t=10,alive=true;c.innerHTML='<div style="padding:16px;text-align:center;color:#fff"><div style="font-size:14px;margin-bottom:8px">🏆 Click the CORRECT number in order! 10 in 10s!</div><div style="font-size:14px;color:#888">Score: <span id="hs-c">0</span>/10 | Time: <span id="hs-t">10</span>s</div><div id="hs-a" style="position:relative;width:260px;height:160px;margin:8px auto;background:#0d0d1a;border-radius:12px;overflow:hidden"></div></div>';var a2=c.querySelector("#hs-a"),ce=c.querySelector("#hs-c"),te=c.querySelector("#hs-t");var nextNum=1,nums=[];function spawnNums(){a2.innerHTML="";nums=[];var taken=[];for(var i=1;i<=10;i++){var x,y,ok;do{x=Math.floor(Math.random()*200);y=Math.floor(Math.random()*120);ok=true;for(var j=0;j<taken.length;j++){if(Math.abs(taken[j][0]-x)<40&&Math.abs(taken[j][1]-y)<40){ok=false;break}}}while(!ok);taken.push([x,y]);var el=document.createElement("div");el.style.cssText="position:absolute;width:32px;height:32px;background:#ffd700;border-radius:50%;cursor:pointer;display:flex;align-items:center;justify-content:center;font-size:14px;font-weight:bold;color:#000;left:"+x+"px;top:"+y+"px";el.textContent=i;nums.push({el:el,val:i});el.addEventListener("click",function(v){return function(){if(!alive)return;if(v===nextNum){nextNum++;s++;ce.textContent=s;a2.removeChild(this);if(s>=10){alive=false;w()}}else{l();alive=false}}}(i));a2.appendChild(el)}}spawnNums();var iv=setInterval(function(){t--;te.textContent=t;if(t<=0){alive=false;clearInterval(iv);if(s<10)l()}},1000)};

G.perfect_combo_challenge=function(c,a){var w=a.onWin,l=a.onLose;var combo=0,target=0,alive=true;c.innerHTML='<div style="padding:16px;text-align:center;color:#fff"><div style="font-size:14px;margin-bottom:8px">💫 Click the matching color! 10 in a row!</div><div style="background:#0d0d1a;border-radius:12px;padding:16px;margin:8px 0;min-height:80px"><div style="font-size:36px;margin-bottom:8px" id="pc-show">🔴</div><div style="font-size:24px;font-weight:bold;margin:8px">Combo: <span id="pc-c">0</span>/10</div><div style="display:flex;justify-content:center;gap:8px">'+[0,1,2].map(function(i){return'<button class="pc-btn" data-idx="'+i+'" style="width:60px;height:60px;background:#1a1a2e;border:2px solid #555;border-radius:12px;font-size:24px;cursor:pointer">'+['🔴','🔵','🟢'][i]+'</button>'}).join('')+'</div></div></div>';var show=c.querySelector("#pc-show"),ce=c.querySelector("#pc-c");var colors=["🔴","🔵","🟢"];function nextRound(){target=Math.floor(Math.random()*3);show.textContent=colors[target]}nextRound();c.querySelectorAll(".pc-btn").forEach(function(btn){btn.addEventListener("click",function(){if(!alive)return;var idx=parseInt(this.dataset.idx);if(idx===target){combo++;ce.textContent=combo;if(combo>=10){alive=false;w()}else nextRound()}else{alive=false;l()}})});};
G.speed_clicker=function(c,a){var w=a.onWin,l=a.onLose;var n=0,t=10,curr,alive=true;c.innerHTML='<div style="padding:16px;text-align:center;color:#fff"><div style="font-size:14px;margin-bottom:8px">⚡ Click the SHOWN NUMBER in sequence! 1-20 in 10s!</div><div style="font-size:40px;font-weight:bold;margin:8px" id="sc-seq">1</div><div style="font-size:14px;color:#888">Progress: <span id="sc-n">0</span>/20 | Time: <span id="sc-t">10</span>s</div><div style="display:flex;justify-content:center;gap:6px;flex-wrap:wrap;max-width:260px;margin:0 auto" id="sc-btns"></div></div>';var seqEl=c.querySelector("#sc-seq"),ne=c.querySelector("#sc-n"),te=c.querySelector("#sc-t"),btns=c.querySelector("#sc-btns");curr=1;var order=[];for(var i=1;i<=20;i++)order.push(i);for(var i=order.length-1;i>0;i--){var j=Math.floor(Math.random()*(i+1));var tmp=order[i];order[i]=order[j];order[j]=tmp}order.forEach(function(v){var b=document.createElement("button");b.style.cssText="width:44px;height:44px;background:#1a1a2e;border:2px solid #555;border-radius:8px;color:#fff;font-size:16px;cursor:pointer";b.textContent=v;b.addEventListener("click",function(){if(!alive)return;if(v===curr){curr++;ne.textContent=curr;seqEl.textContent=curr<=20?curr:"✓";if(curr>20){alive=false;w()}}else{alive=false;l()}});btns.appendChild(b)});var iv=setInterval(function(){t--;te.textContent=t;if(t<=0){alive=false;clearInterval(iv);if(curr<=20)l()}},1000)};
